// HasLines applies the HasEdge predicate on the "lines" edge.
func HasLines() predicate.StockTransfer {
	return predicate.StockTransfer(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, LinesTable, LinesColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasLinesWith applies the HasEdge predicate on the "lines" edge with a given conditions (other predicates).
func HasLinesWith(preds ...predicate.StockTransferLine) predicate.StockTransfer {
	return predicate.StockTransfer(func(s *sql.Selector) {
		step := newLinesStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.StockTransfer) predicate.StockTransfer {
	return predicate.StockTransfer(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.StockTransfer) predicate.StockTransfer {
	return predicate.StockTransfer(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.StockTransfer) predicate.StockTransfer {
	return predicate.StockTransfer(sql.NotPredicates(p))
}
